List<int> merge(List<int> a, List<int> b) {
  final out = <int>[];
  var i = 0, j = 0;
  while (i < a.length && j < b.length) {
    out.add(a[i] <= b[j] ? a[i++] : b[j++]);
  }
  return out
    ..addAll(a.sublist(i))
    ..addAll(b.sublist(j));
}

