List<double> movingAvg(List<num> v, int k) {
  final out = <double>[];
  num sum = 0;
  for (var i = 0; i < v.length; i++) {
    sum += v[i];
    if (i >= k) sum -= v[i - k];
    if (i >= k - 1) out.add(sum / k);
  }
  return out;
}

