int minLen(int target, List<int> a) {
  var left = 0, sum = 0, best = a.length + 1;
  for (var right = 0; right < a.length; right++) {
    sum += a[right];
    while (sum >= target) {
      if (right - left + 1 < best) best = right - left + 1;
      sum -= a[left++];
    }
  }
  return best > a.length ? 0 : best;
}

