List<int> sortedSquares(List<int> a) {
  final out = List<int>.filled(a.length, 0);
  var l = 0, r = a.length - 1;
  for (var w = a.length - 1; w >= 0; w--) {
    final x = a[l] * a[l], y = a[r] * a[r];
    if (x > y) {
      out[w] = x;
      l++;
    } else {
      out[w] = y;
      r--;
    }
  }
  return out;
}

void main() {
  print(sortedSquares([-3, -2, 1, 4]));
}
